// Daemon API client. Typed by the generated contract schema
// (src/shared/api/schema.d.ts, regenerated by `task codegen`) — no
// hand-rolled types here, and no code outside this module fetches the
// daemon directly.
import type { components } from './schema';

export type Provider = components['schemas']['Provider'];
export type Model = components['schemas']['Model'];
export type ProviderFailureReason = components['schemas']['ProviderFailureReason'];
export type ProviderOrigin = components['schemas']['ProviderOrigin'];
export type CredentialStatus = components['schemas']['CredentialStatus'];
export type ProviderCredentialKind = NonNullable<components['schemas']['Provider']['credential']>;

/** Explicit credential intent for create/edit (mirrors CredentialInput). */
export type CredentialInput = components['schemas']['CredentialInput'];

/** A typed mutation failure the UI can render with guidance. */
export type MutationFailure = {
  code: 'duplicate_name' | 'origin_protected' | 'provider_limit' | 'keyring_unavailable' | 'invalid_provider' | 'invalid_request' | 'daemon';
  message: string;
};

/** Discriminated mutation result: check `ok` to narrow. */
export type MutationOutcome = { ok: true; provider?: Provider } | (MutationFailure & { ok: false });

// The SPA always reaches the daemon same-origin: the Vite dev server
// proxies /api and /healthz to the loopback daemon (see vite.config.ts),
// and the desktop shell serves the SPA from the same host later.
const BASE = '';

/** A daemon call failed before producing a usable response. */
export class ApiError extends Error {
  constructor(
    readonly kind: 'network' | 'http',
    message: string,
    readonly status?: number,
  ) {
    super(message);
  }
}

async function getJSON(path: string): Promise<unknown> {
  let res: Response;
  try {
    res = await fetch(`${BASE}${path}`, { headers: { Accept: 'application/json' } });
  } catch (err) {
    throw new ApiError('network', `daemon unreachable (${String(err)})`);
  }
  if (!res.ok) {
    throw new ApiError('http', `daemon answered ${res.status} for ${path}`, res.status);
  }
  return res.json();
}

/** List the configured providers. Throws ApiError (e.g. daemon down). */
export async function listProviders(): Promise<Provider[]> {
  const body = (await getJSON('/api/providers')) as components['schemas']['ProviderList'];
  return body.providers;
}

/** Why a model-discovery request failed, in UI-usable terms. */
export type ModelsFailureReason = ProviderFailureReason | 'unknown' | 'daemon';

export type ModelsResult = { ok: true; models: Model[] } | { ok: false; reason: ModelsFailureReason; message: string };

/**
 * Discover one provider's models through the daemon. Returns a
 * discriminated result instead of throwing so Settings can render typed
 * failure states directly.
 */
export async function listProviderModels(name: string): Promise<ModelsResult> {
  let res: Response;
  try {
    res = await fetch(`${BASE}/api/providers/${encodeURIComponent(name)}/models`, {
      headers: { Accept: 'application/json' },
    });
  } catch (err) {
    return { ok: false, reason: 'daemon', message: `daemon unreachable (${String(err)})` };
  }
  if (res.status === 404) {
    const body = (await res.json().catch(() => null)) as components['schemas']['Error'] | null;
    return { ok: false, reason: 'unknown', message: body?.message ?? 'provider is not configured' };
  }
  if (res.status === 502) {
    const body = (await res.json().catch(() => null)) as components['schemas']['ProviderError'] | null;
    if (body?.reason) {
      return { ok: false, reason: body.reason, message: body.message };
    }
    return { ok: false, reason: 'malformed', message: 'provider request failed' };
  }
  if (!res.ok) {
    return { ok: false, reason: 'daemon', message: `daemon answered ${res.status}` };
  }
  const body = (await res.json()) as components['schemas']['ModelList'];
  return { ok: true, models: body.models };
}

async function mutate(method: 'POST' | 'PATCH' | 'DELETE', path: string, body?: unknown): Promise<MutationOutcome> {
  let res: Response;
  try {
    res = await fetch(`${BASE}${path}`, {
      method,
      headers: body === undefined ? { Accept: 'application/json' } : { Accept: 'application/json', 'Content-Type': 'application/json' },
      body: body === undefined ? undefined : JSON.stringify(body),
    });
  } catch (err) {
    return { ok: false, code: 'daemon', message: `daemon unreachable (${String(err)})` };
  }
  if (res.status === 204 || res.ok) {
    if (res.status === 204) return { ok: true };
    return { ok: true, provider: (await res.json()) as Provider };
  }
  const errBody = (await res.json().catch(() => null)) as components['schemas']['Error'] | null;
  const code = errBody?.code as MutationFailure['code'] | undefined;
  return { ok: false, code: code ?? 'daemon', message: errBody?.message ?? `daemon answered ${res.status}` };
}

/** Create a provider (daemon-managed file; key goes to the OS keyring). */
export function createProvider(name: string, baseUrl: string, credential?: CredentialInput): Promise<MutationOutcome> {
  return mutate('POST', '/api/providers', { name, base_url: baseUrl, ...(credential ? { credential } : {}) });
}

export type ProviderUpdate = { name?: string; base_url?: string; credential?: CredentialInput }; // shape mirrors the generated ProviderUpdate

/** Edit a daemon-managed provider (absent fields retain). */
export function updateProvider(name: string, patch: ProviderUpdate): Promise<MutationOutcome> {
  return mutate('PATCH', `/api/providers/${encodeURIComponent(name)}`, patch);
}

/** Delete a daemon-managed provider. */
export function deleteProvider(name: string): Promise<MutationOutcome> {
  return mutate('DELETE', `/api/providers/${encodeURIComponent(name)}`);
}

/** One flat catalog entry (group/namespace client-side). */
export type CatalogModel = components['schemas']['ModelEntry'];

/** The daemon's in-memory model catalog (manual-refresh semantics). */
export async function getModels(): Promise<CatalogModel[]> {
  const body = (await getJSON('/api/models')) as components['schemas']['ModelCatalog'];
  return body.models ?? [];
}

/** Manual refresh: live-fetch one provider's models, updating the catalog. */
export async function refreshProviderModels(name: string): Promise<ModelsResult> {
  let res: Response;
  try {
    res = await fetch(`${BASE}/api/providers/${encodeURIComponent(name)}/models/refresh`, {
      method: 'POST',
      headers: { Accept: 'application/json', 'Content-Type': 'application/json' },
    });
  } catch (err) {
    return { ok: false, reason: 'daemon', message: `daemon unreachable (${String(err)})` };
  }
  if (res.status === 404) {
    return { ok: false, reason: 'unknown', message: 'provider is not configured' };
  }
  if (res.status === 502) {
    const body = (await res.json().catch(() => null)) as components['schemas']['ProviderError'] | null;
    if (body?.reason) return { ok: false, reason: body.reason, message: body.message };
    return { ok: false, reason: 'malformed', message: 'provider request failed' };
  }
  if (!res.ok) return { ok: false, reason: 'daemon', message: `daemon answered ${res.status}` };
  const body = (await res.json()) as components['schemas']['ModelList'];
  return { ok: true, models: body.models };
}
